class.description:
Assign one to a property with [method NetwMemberConfig.quantize]. One quantizer can be shared by many properties. Both peers must use the same settings.
[codeblock]
Netw.configure_property(self, &"position").quantize(NetwQuantizeScalar.new())
[/codeblock]
Use [NetwQuantizeScalar], [NetwQuantizeAngle], [NetwQuantizeQuaternion], [NetwQuantizeTransform2D] or [NetwQuantizeTransform3D], or extend this class. A value is split into [method _stride] integers of [method _bit_width] bits each. [method _encode] returns one of them and [method _decode] rebuilds the value from all of them. Override the methods that start with an underscore, and call the ones without.
[codeblock]
extends NetwQuantize

func _supports_type(type: Variant.Type) -> bool:
    return type == TYPE_VECTOR2

func _bit_width(_type: Variant.Type) -> int:
    return 10

func _stride(_type: Variant.Type) -> int:
    return 2

func _encode(value: Variant, element: int) -> int:
    return roundi((value as Vector2)[element]) & 0x3ff

func _decode(codes: PackedInt64Array, _type: Variant.Type) -> Variant:
    return Vector2(float(codes[0]), float(codes[1]))
[/codeblock]
